<span class="line"><span style="color:#ABB2BF;">    tot_answer, _ </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> tree_of_thought_solve</span><span style="color:#ABB2BF;">(question, client, model)</span></span>
